mapper.select:
select sys_account_id, CONCAT(CAST(money/100 AS DECIMAL(10,2)),'') AS money, description, IFNULL(type_id,'1') AS type_id, CASE WHEN type_id is NULL THEN '餐饮' ELSE categories END categories, date_format(create_time,'%m月%d日') as 'create_time' from `sys_account` where (sys_user_id = #{userId}
or sys_user_id = #{linkUserId}
)
and date_format(create_time,'%Y-%m') = #{yearMonth}
and del_flag = '0' order by create_time desc

SELECT
CONCAT(CAST(sum(money)/100 AS DECIMAL(10,2)),'') AS money,COUNT(1) AS num
FROM `sys_account`
where (sys_user_id = #{userId}

    or sys_user_id = #{linkUserId}

)

    and date_format(create_time,'%Y-%m') = #{yearMonth}

and del_flag = '0'

SELECT
CONCAT(CAST(SUM(money)/100 AS DECIMAL(10,2)),'') AS money,
any_value(categories) AS categories,
COUNT(1) AS num,
type_id
FROM `sys_account`
WHERE (sys_user_id = #{userId}

    OR sys_user_id = #{linkUserId}

)

    AND DATE_FORMAT(create_time,'%Y-%m') = #{yearMonth}

AND del_flag = '0'
GROUP BY type_id

SELECT
CONCAT(CAST(SUM(money)/100 AS DECIMAL(10,2)),'') AS money,DATE_FORMAT(create_time,'%e')  AS 'day'
FROM `sys_account`
WHERE (sys_user_id = #{userId}

    OR sys_user_id = #{linkUserId}

)

    AND DATE_FORMAT(create_time,'%Y-%m') = #{yearMonth}

AND del_flag = '0'
GROUP BY DATE_FORMAT(create_time,'%e')

select sys_account_id, CONCAT(CAST(money/100 AS DECIMAL(10,2)),'') AS money, description, IFNULL(type_id,'1') AS type_id, CASE WHEN type_id is NULL THEN '餐饮' ELSE categories END categories, date_format(create_time,'%m月%d日') as 'create_time' from `sys_account` where (sys_user_id = #{userId}
or sys_user_id = #{linkUserId}
)
and date_format(create_time,'%Y-%m') = #{yearMonth}
and del_flag = '0' ORDER BY money+0 DESC LIMIT 0,10

SELECT
CONCAT(CAST(SUM(money)/100 AS DECIMAL(10,2)),'') AS money,any_value(DATE_FORMAT(create_time,'%Y年%c月'))  AS 'month'
FROM `sys_account`
WHERE (sys_user_id = #{userId}

    OR sys_user_id = #{linkUserId}

)
AND DATE_FORMAT(create_time,'%Y-%m') <= DATE_FORMAT(NOW(),'%Y-%m')
AND DATE_FORMAT(create_time,'%Y-%m') >= DATE_FORMAT(SUBDATE(NOW(), INTERVAL 5 MONTH),'%Y-%m')
AND del_flag = '0'
GROUP BY DATE_FORMAT(create_time,'%Y-%c')

select sys_account_id, CONCAT(CAST(money/100 AS DECIMAL(10,2)),'') AS money, description, IFNULL(type_id,'1') AS type_id, CASE WHEN type_id is NULL THEN '餐饮' ELSE categories END categories, date_format(create_time,'%m月%d日') as 'create_time' from `sys_account` where (sys_user_id = #{userId}
or sys_user_id = #{linkUserId}
)
and date_format(create_time,'%Y-%m') = #{yearMonth}
and del_flag = '0' and type_id = #{typeId} ORDER BY money+0 DESC
